import{_ as e,o as t,c as d,a0 as i}from"./chunks/framework.Bmhw_dvp.js";const b=JSON.parse('{"title":"管理后台与权限","description":"","frontmatter":{},"headers":[],"relativePath":"basic/admin.md","filePath":"basic/admin.md","lastUpdated":1793354072000}'),o={name:"basic/admin.md"};function r(l,a,n,c,s,h){return t(),d("div",null,[...a[0]||(a[0]=[i('<h1 id="管理后台与权限" tabindex="-1">管理后台与权限 <a class="header-anchor" href="#管理后台与权限" aria-label="Permalink to &quot;管理后台与权限&quot;">​</a></h1><h2 id="角色模型" tabindex="-1">角色模型 <a class="header-anchor" href="#角色模型" aria-label="Permalink to &quot;角色模型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>权限</th></tr></thead><tbody><tr><td><code>root</code></td><td>全部房间控制 / 删除、用户审核、角色管理、系统设置、更新</td></tr><tr><td><code>admin</code></td><td>创建并完全控制自己的房间</td></tr><tr><td><code>user</code></td><td>加入房间、评论弹幕（审核通过的注册用户）</td></tr><tr><td><code>guest</code></td><td>同 user（未登录或未审核用户）</td></tr></tbody></table><p>新用户注册后为 <code>guest</code> + <code>pending</code>，需 root 在管理后台审核通过后升级为 <code>user</code>。</p><h2 id="用户管理" tabindex="-1">用户管理 <a class="header-anchor" href="#用户管理" aria-label="Permalink to &quot;用户管理&quot;">​</a></h2><p>用户列表、审核注册申请、修改角色（仅 admin / user 之间）、删除用户。</p><h2 id="房间管理" tabindex="-1">房间管理 <a class="header-anchor" href="#房间管理" aria-label="Permalink to &quot;房间管理&quot;">​</a></h2><p>查看活跃房间；强制关闭单个房间（admin / root）、批量删除与清空全部（root）；清理无人房间。</p><h2 id="系统设置" tabindex="-1">系统设置 <a class="header-anchor" href="#系统设置" aria-label="Permalink to &quot;系统设置&quot;">​</a></h2><ul><li>注册方式：直接注册 / 审批注册 / 禁止注册。</li><li>房间：无人访问自动清理（开关 + 超时小时数）、一起听默认音量、建房权限（仅管理员 / 所有登录用户）、房间权限矩阵（添加影片、移除切换、音乐队列、踢人、禁言五类动作 × 房管 / 管理员 / 普通用户）。</li><li>语音：自定义 LiveKit 服务器地址（留空按页面域名推导）。</li><li>公告：版本更新后是否自动弹出；公告正文取仓库根目录的 <code>announce.md</code>。</li><li>功能开关：Beta 功能（Kazumi、AniSubs 番剧源、B站视频下载），开启后可填规则源与 TVBox 采集源；禁用服务器端 DASH 模式；B站默认解析参数（普通视频 / 番剧影视）。</li><li>测试开关：允许单用户在多个页面同时登录同一房间（仅供调试，语音成员表会出现重名）。</li><li>更新：是否接收预发布版本、是否使用镜像更新源、CDN 加速（仅 GitHub 源生效）。</li></ul><p>Bilibili 登录凭证按用户绑定（个人资料页），用于大会员清晰度解析，不属于系统设置项。</p><h2 id="更新" tabindex="-1">更新 <a class="header-anchor" href="#更新" aria-label="Permalink to &quot;更新&quot;">​</a></h2><p>管理后台可检查并应用新版本：默认读 GitCode 镜像上的版本清单（国内直连），关掉镜像开关改走 GitHub Release；也可手动上传压缩包。桌面版由 GUI 自己检查更新，网页端在托管模式下不显示更新入口。机制见<a href="/advanced/build-update">构建与更新</a>；管理接口清单见 <a href="/advanced/api">API 参考</a>。</p>',13)])])}const p=e(o,[["render",r]]);export{b as __pageData,p as default};
